import { readdir, stat } from "node:fs/promises";
import { basename, extname, isAbsolute, join, relative, resolve, sep } from "node:path";
import type { Language, RawComment } from "./types.ts";

export const EXCLUDED_DIR_SEGMENTS = new Set([
  "node_modules",
  ".git",
  ".next",
  "out",
  "dist",
  "build",
  "target",
  "DerivedData",
  "Gond.xcodeproj",
  ".kotlin",
  ".wrangler",
  "coverage",
]);

export const EXCLUDED_DIR_PREFIXES = [
  "packages/box/test/artifacts/",
  "apps/desktop/src-tauri/gen/",
  "apps/desktop/src-tauri/permissions/autogenerated/",
  "apps/desktop/src-tauri/icons/",
  "apps/desktop/src/fonts/",
  ".agents/skills/",
];

export const EXCLUDED_FILES = new Set([
  "apps/web/next-env.d.ts",
  "apps/web/AGENTS.md",
  "packages/shared/brand/gond-mark.svg",
  "apps/desktop/src/logo.svg",
  "apps/desktop/src/team.svg",
  "apps/ios/AppIcon.icon/Assets/cog.svg",
  "bun.lock",
  "apps/desktop/src-tauri/Cargo.lock",
]);

const GENERATED_HEADER_PATTERN =
  /@generated\b|code generated by|do not edit|auto-generated|this file is automatically generated/i;

export function toPosixPath(filePath: string): string {
  return sep === "/" ? filePath : filePath.split(sep).join("/");
}

export function compareStrings(a: string, b: string): number {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

export function detectLanguage(relPosixPath: string): Language | null {
  const base = basename(relPosixPath);
  if (base === "Dockerfile" || base.endsWith(".Dockerfile") || base.startsWith("Dockerfile.")) {
    return "dockerfile";
  }
  const ext = extname(base).toLowerCase();
  switch (ext) {
    case ".ts":
    case ".mts":
    case ".cts":
      return "ts";
    case ".tsx":
      return "tsx";
    case ".js":
    case ".mjs":
    case ".cjs":
      return "js";
    case ".jsx":
      return "jsx";
    case ".swift":
      return "swift";
    case ".kt":
    case ".kts":
      return "kotlin";
    case ".rs":
      return "rust";
    case ".css":
      return "css";
    case ".html":
    case ".htm":
      return "html";
    case ".xml":
      return "xml";
    case ".sh":
    case ".bash":
      return "shell";
    case ".yml":
    case ".yaml":
      return "yaml";
    case ".toml":
      return "toml";
    case ".jsonc":
      return "jsonc";
    case ".pro":
      return "proguard";
    case ".properties":
      return "properties";
    default:
      return null;
  }
}

export function isExcludedPath(relPosixPath: string): boolean {
  const normalized = relPosixPath.replace(/^\.\//, "");
  if (EXCLUDED_FILES.has(normalized)) return true;
  for (const prefix of EXCLUDED_DIR_PREFIXES) {
    if (normalized.startsWith(prefix) || `${normalized}/` === prefix) {
      return true;
    }
  }
  const segments = normalized.split("/");
  for (let i = 0; i < segments.length - 1; i++) {
    if (EXCLUDED_DIR_SEGMENTS.has(segments[i])) return true;
  }
  return false;
}

export function isExcludedDirectory(relPosixDir: string): boolean {
  const normalized = relPosixDir.replace(/^\.\//, "").replace(/\/+$/, "");
  if (!normalized) return false;
  const withSlash = `${normalized}/`;
  for (const prefix of EXCLUDED_DIR_PREFIXES) {
    if (withSlash === prefix || withSlash.startsWith(prefix)) {
      return true;
    }
  }
  for (const segment of normalized.split("/")) {
    if (EXCLUDED_DIR_SEGMENTS.has(segment)) return true;
  }
  return false;
}

export function hasGeneratedFileHeader(rawComments: RawComment[]): boolean {
  for (const comment of rawComments) {
    if (comment.startLine > 10) break;
    if (GENERATED_HEADER_PATTERN.test(comment.text)) {
      return true;
    }
  }
  return false;
}

export function normalizeTargetPaths(root: string, targetPaths: string[]): string[] {
  const resolvedRoot = resolve(root);
  const result: string[] = [];
  for (const input of targetPaths) {
    const abs = isAbsolute(input) ? resolve(input) : resolve(resolvedRoot, input);
    const rel = toPosixPath(relative(resolvedRoot, abs));
    if (rel === "" || rel === ".") {
      return [""];
    }
    if (rel.startsWith("../") || rel === "..") {
      throw new Error(`Path "${input}" is outside root "${resolvedRoot}"`);
    }
    result.push(rel.replace(/\/+$/, ""));
  }
  return result;
}

export function createScopeMatcher(root: string, targetPaths: string[]): (relPosixPath: string) => boolean {
  if (targetPaths.length === 0) {
    return () => true;
  }
  const normalized = normalizeTargetPaths(root, targetPaths);
  if (normalized.includes("")) {
    return () => true;
  }
  return (relPosixPath: string) => {
    const candidate = relPosixPath.replace(/^\.\//, "");
    for (const target of normalized) {
      if (candidate === target || candidate.startsWith(`${target}/`)) {
        return true;
      }
    }
    return false;
  };
}

function isInsideGitRepo(root: string): boolean {
  const proc = Bun.spawnSync(["git", "-C", root, "rev-parse", "--is-inside-work-tree"], {
    stdout: "pipe",
    stderr: "pipe",
  });
  return proc.exitCode === 0 && proc.stdout.toString("utf8").trim() === "true";
}

async function isRegularFile(absPath: string): Promise<boolean> {
  try {
    const info = await stat(absPath);
    return info.isFile();
  } catch {
    return false;
  }
}

async function walkDirectory(root: string, relDir: string, out: string[]): Promise<void> {
  if (isExcludedDirectory(relDir)) return;
  const absDir = relDir ? join(root, relDir) : root;
  let entries;
  try {
    entries = await readdir(absDir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const relPath = relDir ? `${relDir}/${entry.name}` : entry.name;
    if (entry.isDirectory()) {
      if (!isExcludedDirectory(relPath)) {
        await walkDirectory(root, relPath, out);
      }
    } else if (entry.isFile()) {
      out.push(relPath);
    } else if (entry.isSymbolicLink()) {
      if (await isRegularFile(join(root, relPath))) {
        out.push(relPath);
      }
    }
  }
}

export interface DiscoveredFile {
  relPath: string;
  absPath: string;
  language: Language;
}

export async function discoverFiles(root: string, targetPaths: string[] = []): Promise<DiscoveredFile[]> {
  const resolvedRoot = resolve(root);
  const normalizedTargets = targetPaths.length > 0 ? normalizeTargetPaths(resolvedRoot, targetPaths) : [];
  const rawRelPaths = new Set<string>();

  if (isInsideGitRepo(resolvedRoot)) {
    const args = ["git", "-C", resolvedRoot, "ls-files", "-z", "--cached", "--others", "--exclude-standard"];
    if (normalizedTargets.length > 0 && !normalizedTargets.includes("")) {
      args.push("--", ...normalizedTargets);
    }
    const proc = Bun.spawnSync(args, { stdout: "pipe", stderr: "pipe" });
    if (proc.exitCode === 0) {
      const items = proc.stdout.toString("utf8").split("\0");
      for (const item of items) {
        if (item) rawRelPaths.add(toPosixPath(item));
      }
    } else {
      await collectWithWalk(resolvedRoot, normalizedTargets, rawRelPaths);
    }
  } else {
    await collectWithWalk(resolvedRoot, normalizedTargets, rawRelPaths);
  }

  const discovered: DiscoveredFile[] = [];
  const sorted = [...rawRelPaths].sort(compareStrings);
  for (const relPath of sorted) {
    if (isExcludedPath(relPath)) continue;
    const language = detectLanguage(relPath);
    if (!language) continue;
    const absPath = join(resolvedRoot, relPath);
    if (!(await isRegularFile(absPath))) continue;
    discovered.push({ relPath, absPath, language });
  }
  return discovered;
}

async function collectWithWalk(root: string, normalizedTargets: string[], out: Set<string>): Promise<void> {
  if (normalizedTargets.length === 0 || normalizedTargets.includes("")) {
    const files: string[] = [];
    await walkDirectory(root, "", files);
    for (const file of files) out.add(file);
    return;
  }
  for (const target of normalizedTargets) {
    const absTarget = join(root, target);
    let info;
    try {
      info = await stat(absTarget);
    } catch {
      continue;
    }
    if (info.isFile()) {
      out.add(target);
    } else if (info.isDirectory()) {
      const files: string[] = [];
      await walkDirectory(root, target, files);
      for (const file of files) out.add(file);
    }
  }
}
